const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');
const from = String(body.from || body.telefone || '').replace(/\D/g, '');
if (!from) throw new Error('missing from/telefone');
const text = String(body.text || '').trim();
const correlationId = headers['x-correlation-id'] || headers['X-Correlation-Id'] || `typebot-${Date.now()}`;
const idempotencyKey = headers['idempotency-key'] || headers['Idempotency-Key'] || body?.rawMessage?.messageId || `${from}-${Date.now()}`;
return [{
  json: {
    correlationId,
    idempotencyKey,
    payload: {
      from,
      text,
      rawMessage: {
        provider: 'typebot',
        messageId: idempotencyKey,
        timestamp: new Date().toISOString(),
        channel: 'whatsapp',
        source: flowEnv,
        original: body
      }
    }
  }
}];

const backend = $input.first().json || {};
const ctx = $('Build Payload').first().json;
return [{ json: { ok: true, correlationId: ctx.correlationId, duplicate: Boolean(backend.duplicate), atendimento: backend.atendimento || null, success: backend.success !== false } }];
